/** Original Second Wind planner. Imports only the feature modules bought by the caller. */
const optional = ['status-index','expiry','recovery','change-stream'];
export function prepare(config, features = []) {
  if (!config || Array.isArray(config) || typeof config !== 'object') throw new Error('configuration_required');
  if (Object.keys(config).some(key => !['language','table_name'].includes(key))) throw new Error('unknown_configuration_field');
  if (config.language !== 'javascript') throw new Error(config.language ? 'unsupported_language' : 'explicit_language_required');
  if (typeof config.table_name !== 'string' || !/^[A-Za-z0-9_.-]{3,255}$/.test(config.table_name)) throw new Error('invalid_table_name');
  if (!Array.isArray(features) || [...features].some(feature => !feature || !optional.includes(feature.id) || typeof feature.apply !== 'function')
      || new Set(features.map(feature => feature.id)).size !== features.length) throw new Error('invalid_feature_modules');
  const implementations = new Map(features.map(feature => [feature.id,feature]));
  const selected = ['table',...implementations.keys()];
  const TableName = config.table_name;
  const input = {TableName,BillingMode:'PAY_PER_REQUEST',
    AttributeDefinitions:[{AttributeName:'agent_id',AttributeType:'S'},{AttributeName:'session_id',AttributeType:'S'}],
    KeySchema:[{AttributeName:'agent_id',KeyType:'HASH'},{AttributeName:'session_id',KeyType:'RANGE'}],
    SSESpecification:{Enabled:true,SSEType:'KMS'}};
  const steps = [{id:'create',operation:'CreateTable',input},
    {id:'active',operation:'DescribeTable',input:{TableName},depends_on:['create'],wait_for:{path:'Table.TableStatus',equals:'ACTIVE',timeout_seconds:600,poll_seconds:5}}];
  const checks = {'Table.TableStatus':'ACTIVE','Table.TableName':TableName,
    'Table.BillingModeSummary.BillingMode':'PAY_PER_REQUEST',
    'Table.AttributeDefinitions':input.AttributeDefinitions.map(value => ({...value})),
    'Table.KeySchema':input.KeySchema.map(value => ({...value})),
    'Table.SSEDescription.Status':'ENABLED','Table.SSEDescription.SSEType':'KMS'};
  const verification = [{operation:'DescribeTable',input:{TableName},checks}];
  for (const id of optional) if (implementations.has(id)) implementations.get(id).apply({TableName,input,steps,checks,verification});
  return {schema_version:'1',sku:'AWS-0568',target:'aws-dynamodb-api',components:[...selected].sort(),steps,verification,
    execution:'buyer-controlled',recovery:'Inspect existing table configuration after a lost response. Do not treat a name collision as proof that the intended table was created.'};
}

"""Original Second Wind planner. No SDK, subprocess, credentials or network calls."""
import re

OPTIONAL = ('status-index', 'expiry', 'recovery', 'change-stream')


def prepare(config, features=()):
    if not isinstance(config, dict):
        raise ValueError('configuration_required')
    if set(config) - {'language', 'table_name'}:
        raise ValueError('unknown_configuration_field')
    if config.get('language') != 'python':
        raise ValueError('unsupported_language' if config.get('language') else 'explicit_language_required')
    table_name = config.get('table_name')
    if not isinstance(table_name, str) or re.fullmatch(r'[A-Za-z0-9_.-]{3,255}', table_name) is None:
        raise ValueError('invalid_table_name')
    if not isinstance(features, (list, tuple)) or any(not isinstance(feature, dict) or feature.get('id') not in OPTIONAL or not callable(feature.get('apply')) for feature in features):
        raise ValueError('invalid_feature_modules')
    implementations = {feature['id']: feature['apply'] for feature in features}
    if len(implementations) != len(features):
        raise ValueError('invalid_feature_modules')
    selected = ['table', *implementations]
    request = {'TableName': table_name, 'BillingMode': 'PAY_PER_REQUEST',
               'AttributeDefinitions': [{'AttributeName': 'agent_id', 'AttributeType': 'S'}, {'AttributeName': 'session_id', 'AttributeType': 'S'}],
               'KeySchema': [{'AttributeName': 'agent_id', 'KeyType': 'HASH'}, {'AttributeName': 'session_id', 'KeyType': 'RANGE'}],
               'SSESpecification': {'Enabled': True, 'SSEType': 'KMS'}}
    steps = [{'id': 'create', 'operation': 'CreateTable', 'input': request},
             {'id': 'active', 'operation': 'DescribeTable', 'input': {'TableName': table_name}, 'depends_on': ['create'],
              'wait_for': {'path': 'Table.TableStatus', 'equals': 'ACTIVE', 'timeout_seconds': 600, 'poll_seconds': 5}}]
    checks = {'Table.TableStatus': 'ACTIVE', 'Table.TableName': table_name, 'Table.BillingModeSummary.BillingMode': 'PAY_PER_REQUEST',
              'Table.AttributeDefinitions': [dict(value) for value in request['AttributeDefinitions']],
              'Table.KeySchema': [dict(value) for value in request['KeySchema']],
              'Table.SSEDescription.Status': 'ENABLED', 'Table.SSEDescription.SSEType': 'KMS'}
    verification = [{'operation': 'DescribeTable', 'input': {'TableName': table_name}, 'checks': checks}]
    state = {'TableName': table_name, 'input': request, 'steps': steps, 'checks': checks, 'verification': verification}
    for name in OPTIONAL:
        if name in implementations:
            implementations[name](state)
    return {'schema_version': '1', 'sku': 'AWS-0568', 'target': 'aws-dynamodb-api', 'components': sorted(selected),
            'steps': steps, 'verification': verification, 'execution': 'buyer-controlled',
            'recovery': 'Inspect existing table configuration after a lost response. Do not treat a name collision as proof that the intended table was created.'}

def apply(state):
    name = state['TableName']
    state['steps'].append({'id': 'expiry', 'operation': 'UpdateTimeToLive', 'input': {'TableName': name, 'TimeToLiveSpecification': {'AttributeName': 'expires_at', 'Enabled': True}}, 'depends_on': ['active']})
    state['verification'].append({'operation': 'DescribeTimeToLive', 'input': {'TableName': name}, 'checks': {'TimeToLiveDescription.TimeToLiveStatus': 'ENABLED', 'TimeToLiveDescription.AttributeName': 'expires_at'}})


feature = {'id': 'expiry', 'apply': apply}

def apply(state):
    name = state['TableName']
    state['steps'].append({'id': 'recovery', 'operation': 'UpdateContinuousBackups', 'input': {'TableName': name, 'PointInTimeRecoverySpecification': {'PointInTimeRecoveryEnabled': True}}, 'depends_on': ['active']})
    state['verification'].append({'operation': 'DescribeContinuousBackups', 'input': {'TableName': name}, 'checks': {'ContinuousBackupsDescription.ContinuousBackupsStatus': 'ENABLED', 'ContinuousBackupsDescription.PointInTimeRecoveryDescription.PointInTimeRecoveryStatus': 'ENABLED'}})


feature = {'id': 'recovery', 'apply': apply}

def apply(state):
    state['input']['StreamSpecification'] = {'StreamEnabled': True, 'StreamViewType': 'NEW_AND_OLD_IMAGES'}
    state['checks']['Table.StreamSpecification'] = {'StreamEnabled': True, 'StreamViewType': 'NEW_AND_OLD_IMAGES'}


feature = {'id': 'change-stream', 'apply': apply}
